const ABI_NAMES = [
    "zero", "ra", "sp",  "gp",  "tp", "t0", "t1", "t2",
    "s0",   "s1", "a0",  "a1",  "a2", "a3", "a4", "a5",
    "a6",   "a7", "s2",  "s3",  "s4", "s5", "s6", "s7",
    "s8",   "s9", "s10", "s11", "t3", "t4", "t5", "t6"
];

function signExtend(val, bits) {
    const shift = 32 - bits;
    return (val << shift) >> shift;
}

function hex32(val) {
    return "0x" + (val >>> 0).toString(16).toUpperCase().padStart(8, "0");
}

function hexWordRaw(val) {
    return (val >>> 0).toString(16).toUpperCase().padStart(8, "0");
}

class Memory32 {
    constructor() {
        this.pages = new Map(); // pageIndex (addr >>> 12) -> Uint8Array(4096)
    }

    reset() {
        this.pages.clear();
    }

    read8(addr) {
        addr = addr >>> 0;
        const page = this.pages.get(addr >>> 12);
        return page ? page[addr & 0xFFF] : 0;
    }

    write8(addr, val) {
        addr = addr >>> 0;
        const idx = addr >>> 12;
        let page = this.pages.get(idx);
        if (!page) {
            page = new Uint8Array(4096);
            this.pages.set(idx, page);
        }
        page[addr & 0xFFF] = val & 0xFF;
    }

    read16(addr) {
        return this.read8(addr) | (this.read8(addr + 1) << 8);
    }

    write16(addr, val) {
        this.write8(addr, val & 0xFF);
        this.write8(addr + 1, (val >>> 8) & 0xFF);
    }

    read32(addr) {
        return (
            this.read8(addr) |
            (this.read8(addr + 1) << 8) |
            (this.read8(addr + 2) << 16) |
            (this.read8(addr + 3) << 24)
        ) >>> 0;
    }

    write32(addr, val) {
        this.write8(addr, val & 0xFF);
        this.write8(addr + 1, (val >>> 8) & 0xFF);
        this.write8(addr + 2, (val >>> 16) & 0xFF);
        this.write8(addr + 3, (val >>> 24) & 0xFF);
    }

    writeBlock(baseAddr, uint8Arr) {
        for (let i = 0; i < uint8Arr.length; i++) {
            this.write8((baseAddr + i) >>> 0, uint8Arr[i]);
        }
    }
}

function disassembleInstruction(instr, pc, symbols) {
    instr = instr >>> 0;
    const opcode = instr & 0x7F;
    const rd     = (instr >>> 7) & 0x1F;
    const funct3 = (instr >>> 12) & 0x07;
    const rs1    = (instr >>> 15) & 0x1F;
    const rs2    = (instr >>> 20) & 0x1F;
    const funct7 = (instr >>> 25) & 0x7F;

    const imm_i = signExtend(instr >>> 20, 12);
    const imm_s = signExtend(((instr >>> 25) << 5) | ((instr >>> 7) & 0x1F), 12);
    const imm_b = signExtend(
        (((instr >>> 31) & 1) << 12) |
        (((instr >>> 7)  & 1) << 11) |
        (((instr >>> 25) & 0x3F) << 5) |
        (((instr >>> 8)  & 0x0F) << 1),
        13
    );
    const imm_u = (instr >>> 12) & 0xFFFFF;
    const imm_j = signExtend(
        (((instr >>> 31) & 1) << 20) |
        (((instr >>> 12) & 0xFF) << 12) |
        (((instr >>> 20) & 1) << 11) |
        (((instr >>> 21) & 0x3FF) << 1),
        21
    );

    const r = (idx) => ABI_NAMES[idx];
    const fmtTarget = (addr) => {
        addr = addr >>> 0;
        const sym = symbols && symbols.get(addr);
        return sym ? `${hex32(addr)} <${sym}>` : hex32(addr);
    };

    switch (opcode) {
        case 0x37:
            return `lui ${r(rd)}, 0x${imm_u.toString(16).toUpperCase()}`;
        case 0x17:
            return `auipc ${r(rd)}, 0x${imm_u.toString(16).toUpperCase()}`;
        case 0x6F: {
            const target = (pc + imm_j) >>> 0;
            return `jal ${r(rd)}, ${imm_j}  # ${fmtTarget(target)}`;
        }
        case 0x67:
            if (funct3 === 0) {
                const suffix = (rd === 0 && rs1 === 1 && imm_i === 0) ? "  # ret" : "";
                return `jalr ${r(rd)}, ${r(rs1)}, ${imm_i}${suffix}`;
            }
            break;
        case 0x63: {
            const bmap = { 0: "beq", 1: "bne", 4: "blt", 5: "bge", 6: "bltu", 7: "bgeu" };
            if (bmap[funct3]) {
                const target = (pc + imm_b) >>> 0;
                return `${bmap[funct3]} ${r(rs1)}, ${r(rs2)}, ${imm_b}  # ${fmtTarget(target)}`;
            }
            break;
        }
        case 0x03: {
            const lmap = { 0: "lb", 1: "lh", 2: "lw", 4: "lbu", 5: "lhu" };
            if (lmap[funct3]) return `${lmap[funct3]} ${r(rd)}, ${imm_i}(${r(rs1)})`;
            break;
        }
        case 0x23: {
            const smap = { 0: "sb", 1: "sh", 2: "sw" };
            if (smap[funct3]) return `${smap[funct3]} ${r(rs2)}, ${imm_s}(${r(rs1)})`;
            break;
        }
        case 0x13: {
            if (instr === 0x00000013) return "addi zero, zero, 0  # nop";
            switch (funct3) {
                case 0: return `addi ${r(rd)}, ${r(rs1)}, ${imm_i}`;
                case 1: if (funct7 === 0x00) return `slli ${r(rd)}, ${r(rs1)}, ${rs2}`; break;
                case 2: return `slti ${r(rd)}, ${r(rs1)}, ${imm_i}`;
                case 3: return `sltiu ${r(rd)}, ${r(rs1)}, ${imm_i}`;
                case 4: return `xori ${r(rd)}, ${r(rs1)}, ${imm_i}`;
                case 5:
                    if (funct7 === 0x00) return `srli ${r(rd)}, ${r(rs1)}, ${rs2}`;
                    if (funct7 === 0x20) return `srai ${r(rd)}, ${r(rs1)}, ${rs2}`;
                    break;
                case 6: return `ori ${r(rd)}, ${r(rs1)}, ${imm_i}`;
                case 7: return `andi ${r(rd)}, ${r(rs1)}, ${imm_i}`;
            }
            break;
        }
        case 0x33: {
            if (funct7 === 0x00) {
                const rmap = { 0: "add", 1: "sll", 2: "slt", 3: "sltu", 4: "xor", 5: "srl", 6: "or", 7: "and" };
                if (rmap[funct3]) return `${rmap[funct3]} ${r(rd)}, ${r(rs1)}, ${r(rs2)}`;
            } else if (funct7 === 0x20) {
                if (funct3 === 0) return `sub ${r(rd)}, ${r(rs1)}, ${r(rs2)}`;
                if (funct3 === 5) return `sra ${r(rd)}, ${r(rs1)}, ${r(rs2)}`;
            } else if (funct7 === 0x01) {
                const mmap = { 0: "mul", 1: "mulh", 2: "mulhsu", 3: "mulhu", 4: "div", 5: "divu", 6: "rem", 7: "remu" };
                if (mmap[funct3]) return `${mmap[funct3]} ${r(rd)}, ${r(rs1)}, ${r(rs2)}`;
            }
            break;
        }
        case 0x73:
            if (instr === 0x00000073) return "ecall";
            if (instr === 0x00100073) return "ebreak";
            break;
        case 0x0F:
            return "fence";
    }
    return `.word ${hex32(instr)}`;
}

class RiscVSimulator {
    constructor(logCallback) {
        this.mem = new Memory32();
        this.regs = new Uint32Array(32);
        this.prevRegs = new Uint32Array(32);
        this.pc = 0;
        this.prevPc = 0;
        this.halted = false;
        this.steps = 0;
        this.heapBreak = 0x20000000;
        this.breakpoints = new Set();
        this.symbols = new Map();
        this.codeStart = 0;
        this.codeEnd = 0x100;
        this.lastBuffer = null;
        this.lastFilename = "";
        this.log = logCallback || console.log;
    }

    resetState() {
        this.mem.reset();
        this.regs.fill(0);
        this.prevRegs.fill(0);
        this.pc = 0;
        this.prevPc = 0;
        this.halted = false;
        this.steps = 0;
        this.heapBreak = 0x20000000;
        this.symbols.clear();
    }

    setReg(rd, val) {
        if (rd > 0 && rd < 32) {
            this.regs[rd] = val >>> 0;
        }
        this.regs[0] = 0;
    }

    loadBytes(uint8Arr, filename) {
        this.resetState();
        this.lastBuffer = new Uint8Array(uint8Arr);
        this.lastFilename = filename;

        const dv = new DataView(uint8Arr.buffer, uint8Arr.byteOffset, uint8Arr.byteLength);
        // Detect ELF magic: 0x7F 'E' 'L' 'F'
        if (uint8Arr.length >= 52 &&
            uint8Arr[0] === 0x7F && uint8Arr[1] === 0x45 &&
            uint8Arr[2] === 0x4C && uint8Arr[3] === 0x46) {
            const e_entry     = dv.getUint32(24, true);
            const e_phoff     = dv.getUint32(28, true);
            const e_shoff     = dv.getUint32(32, true);
            const e_phentsize = dv.getUint16(42, true);
            const e_phnum     = dv.getUint16(44, true);
            const e_shentsize = dv.getUint16(46, true);
            const e_shnum     = dv.getUint16(48, true);

            let minAddr = 0xFFFFFFFF;
            let maxAddr = 0;
            let totalBytes = 0;

            for (let i = 0; i < e_phnum; i++) {
                const off = e_phoff + i * e_phentsize;
                const p_type   = dv.getUint32(off + 0, true);
                const p_offset = dv.getUint32(off + 4, true);
                const p_vaddr  = dv.getUint32(off + 8, true);
                const p_filesz = dv.getUint32(off + 16, true);
                const p_memsz  = dv.getUint32(off + 20, true);
                if (p_type === 1 && p_memsz > 0) {
                    const slice = uint8Arr.subarray(p_offset, p_offset + p_filesz);
                    this.mem.writeBlock(p_vaddr, slice);
                    totalBytes += p_filesz;
                    if (p_vaddr < minAddr) minAddr = p_vaddr;
                    if (p_vaddr + p_memsz > maxAddr) maxAddr = p_vaddr + p_memsz;
                }
            }

            // Parse symbol table (.symtab)
            if (e_shoff > 0 && e_shnum > 0) {
                for (let i = 0; i < e_shnum; i++) {
                    const sh = e_shoff + i * e_shentsize;
                    if (sh + 40 > uint8Arr.length) break;
                    const sh_type    = dv.getUint32(sh + 4, true);
                    const sh_offset  = dv.getUint32(sh + 16, true);
                    const sh_size    = dv.getUint32(sh + 20, true);
                    const sh_link    = dv.getUint32(sh + 24, true);
                    const sh_entsize = dv.getUint32(sh + 36, true);
                    if (sh_type === 2 && sh_entsize >= 16 && sh_link < e_shnum) {
                        const strSh = e_shoff + sh_link * e_shentsize;
                        const strOff = dv.getUint32(strSh + 16, true);
                        const strSz  = dv.getUint32(strSh + 20, true);
                        const count  = Math.floor(sh_size / sh_entsize);
                        for (let s = 0; s < count; s++) {
                            const sym = sh_offset + s * sh_entsize;
                            const st_name  = dv.getUint32(sym + 0, true);
                            const st_value = dv.getUint32(sym + 4, true);
                            const st_info  = uint8Arr[sym + 12] & 0xF;
                            const st_shndx = dv.getUint16(sym + 14, true);
                            if (st_name > 0 && st_name < strSz && st_shndx !== 0 && (st_info <= 2)) {
                                let name = "";
                                for (let k = strOff + st_name; k < strOff + strSz && uint8Arr[k] !== 0; k++) {
                                    name += String.fromCharCode(uint8Arr[k]);
                                }
                                if (name && !name.startsWith("$")) {
                                    this.symbols.set(st_value >>> 0, name);
                                }
                            }
                        }
                    }
                }
            }

            this.pc = e_entry >>> 0;
            this.prevPc = this.pc;
            this.codeStart = minAddr === 0xFFFFFFFF ? 0 : minAddr;
            this.codeEnd = maxAddr === 0 ? 0x100 : Math.min(maxAddr, this.codeStart + 0x400);
            this.log(`[ELF32] "${filename}" cargado a memoria (${totalBytes} bytes, entry PC = ${hex32(this.pc)}).
`);
        } else {
            this.mem.writeBlock(0x00000000, uint8Arr);
            this.pc = 0x00000000;
            this.prevPc = 0;
            this.codeStart = 0;
            this.codeEnd = Math.min(Math.max(uint8Arr.length, 64), 0x400);
            this.log(`[RAW BIN] "${filename}" cargado a memoria en 0x00000000 (${uint8Arr.length} bytes).
`);
        }
    }

    step() {
        if (this.halted) {
            return { status: "HALTED", message: "El programa ya ha terminado." };
        }

        this.prevRegs.set(this.regs);
        this.prevPc = this.pc;

        const instr = this.mem.read32(this.pc);
        const opcode = instr & 0x7F;
        const rd     = (instr >>> 7) & 0x1F;
        const funct3 = (instr >>> 12) & 0x07;
        const rs1    = (instr >>> 15) & 0x1F;
        const rs2    = (instr >>> 20) & 0x1F;
        const funct7 = (instr >>> 25) & 0x7F;

        const imm_i = signExtend(instr >>> 20, 12);
        const imm_s = signExtend(((instr >>> 25) << 5) | ((instr >>> 7) & 0x1F), 12);
        const imm_b = signExtend(
            (((instr >>> 31) & 1) << 12) |
            (((instr >>> 7)  & 1) << 11) |
            (((instr >>> 25) & 0x3F) << 5) |
            (((instr >>> 8)  & 0x0F) << 1),
            13
        );
        const imm_j = signExtend(
            (((instr >>> 31) & 1) << 20) |
            (((instr >>> 12) & 0xFF) << 12) |
            (((instr >>> 20) & 1) << 11) |
            (((instr >>> 21) & 0x3FF) << 1),
            21
        );

        let nextPc = (this.pc + 4) >>> 0;
        let isBranchOrJump = false;

        const v1_u = this.regs[rs1] >>> 0;
        const v2_u = this.regs[rs2] >>> 0;
        const v1_s = v1_u | 0;
        const v2_s = v2_u | 0;

        switch (opcode) {
            case 0x37: // lui
                this.setReg(rd, instr & 0xFFFFF000);
                break;
            case 0x17: // auipc
                this.setReg(rd, (this.pc + (instr & 0xFFFFF000)) >>> 0);
                break;
            case 0x6F: // jal
                this.setReg(rd, nextPc);
                nextPc = (this.pc + imm_j) >>> 0;
                isBranchOrJump = true;
                break;
            case 0x67: // jalr
                if (funct3 !== 0) return this.illegal(instr);
                this.setReg(rd, nextPc);
                nextPc = ((v1_u + imm_i) & ~1) >>> 0;
                isBranchOrJump = true;
                break;
            case 0x63: { // branches
                let take = false;
                switch (funct3) {
                    case 0: take = (v1_u === v2_u); break;
                    case 1: take = (v1_u !== v2_u); break;
                    case 4: take = (v1_s < v2_s); break;
                    case 5: take = (v1_s >= v2_s); break;
                    case 6: take = (v1_u < v2_u); break;
                    case 7: take = (v1_u >= v2_u); break;
                    default: return this.illegal(instr);
                }
                if (take) {
                    nextPc = (this.pc + imm_b) >>> 0;
                    isBranchOrJump = true;
                }
                break;
            }
            case 0x03: { // loads
                const addr = (v1_u + imm_i) >>> 0;
                switch (funct3) {
                    case 0: this.setReg(rd, signExtend(this.mem.read8(addr), 8)); break;
                    case 1: this.setReg(rd, signExtend(this.mem.read16(addr), 16)); break;
                    case 2: this.setReg(rd, this.mem.read32(addr)); break;
                    case 4: this.setReg(rd, this.mem.read8(addr)); break;
                    case 5: this.setReg(rd, this.mem.read16(addr)); break;
                    default: return this.illegal(instr);
                }
                break;
            }
            case 0x23: { // stores
                const addr = (v1_u + imm_s) >>> 0;
                switch (funct3) {
                    case 0: this.mem.write8(addr, v2_u & 0xFF); break;
                    case 1: this.mem.write16(addr, v2_u & 0xFFFF); break;
                    case 2: this.mem.write32(addr, v2_u); break;
                    default: return this.illegal(instr);
                }
                break;
            }
            case 0x13: { // op-imm
                switch (funct3) {
                    case 0: this.setReg(rd, (v1_u + imm_i) >>> 0); break;
                    case 1:
                        if (funct7 !== 0x00) return this.illegal(instr);
                        this.setReg(rd, (v1_u << rs2) >>> 0);
                        break;
                    case 2: this.setReg(rd, (v1_s < imm_i) ? 1 : 0); break;
                    case 3: this.setReg(rd, (v1_u < (imm_i >>> 0)) ? 1 : 0); break;
                    case 4: this.setReg(rd, (v1_u ^ imm_i) >>> 0); break;
                    case 5:
                        if (funct7 === 0x00) this.setReg(rd, v1_u >>> rs2);
                        else if (funct7 === 0x20) this.setReg(rd, (v1_s >> rs2) >>> 0);
                        else return this.illegal(instr);
                        break;
                    case 6: this.setReg(rd, (v1_u | imm_i) >>> 0); break;
                    case 7: this.setReg(rd, (v1_u & imm_i) >>> 0); break;
                }
                break;
            }
            case 0x33: { // op
                if (funct7 === 0x00) {
                    switch (funct3) {
                        case 0: this.setReg(rd, (v1_u + v2_u) >>> 0); break;
                        case 1: this.setReg(rd, (v1_u << (v2_u & 0x1F)) >>> 0); break;
                        case 2: this.setReg(rd, (v1_s < v2_s) ? 1 : 0); break;
                        case 3: this.setReg(rd, (v1_u < v2_u) ? 1 : 0); break;
                        case 4: this.setReg(rd, (v1_u ^ v2_u) >>> 0); break;
                        case 5: this.setReg(rd, v1_u >>> (v2_u & 0x1F)); break;
                        case 6: this.setReg(rd, (v1_u | v2_u) >>> 0); break;
                        case 7: this.setReg(rd, (v1_u & v2_u) >>> 0); break;
                    }
                } else if (funct7 === 0x20) {
                    if (funct3 === 0) this.setReg(rd, (v1_u - v2_u) >>> 0);
                    else if (funct3 === 5) this.setReg(rd, (v1_s >> (v2_u & 0x1F)) >>> 0);
                    else return this.illegal(instr);
                } else if (funct7 === 0x01) {
                    const b1_s = BigInt(v1_s), b2_s = BigInt(v2_s);
                    const b1_u = BigInt(v1_u), b2_u = BigInt(v2_u);
                    switch (funct3) {
                        case 0: this.setReg(rd, Number((b1_s * b2_s) & 0xFFFFFFFFn)); break;
                        case 1: this.setReg(rd, Number(((b1_s * b2_s) >> 32n) & 0xFFFFFFFFn)); break;
                        case 2: this.setReg(rd, Number(((b1_s * b2_u) >> 32n) & 0xFFFFFFFFn)); break;
                        case 3: this.setReg(rd, Number(((b1_u * b2_u) >> 32n) & 0xFFFFFFFFn)); break;
                        case 4: this.setReg(rd, v2_s === 0 ? 0xFFFFFFFF : Number((b1_s / b2_s) & 0xFFFFFFFFn)); break;
                        case 5: this.setReg(rd, v2_u === 0 ? 0xFFFFFFFF : Number((b1_u / b2_u) & 0xFFFFFFFFn)); break;
                        case 6: this.setReg(rd, v2_s === 0 ? v1_u : Number((b1_s % b2_s) & 0xFFFFFFFFn)); break;
                        case 7: this.setReg(rd, v2_u === 0 ? v1_u : Number((b1_u % b2_u) & 0xFFFFFFFFn)); break;
                    }
                } else {
                    return this.illegal(instr);
                }
                break;
            }
            case 0x73:
                if (instr === 0x00000073) {
                    this.pc = nextPc;
                    this.steps++;
                    return this.handleEcall();
                } else if (instr === 0x00100073) {
                    this.pc = nextPc;
                    this.steps++;
                    return { status: "EBREAK", message: `EBREAK alcanzado en ${hex32(this.prevPc)}` };
                }
                return this.illegal(instr);
            case 0x0F:
                break;
            default:
                return this.illegal(instr);
        }

        this.steps++;
        const selfLoop = isBranchOrJump && (nextPc === this.pc);
        this.pc = nextPc;

        if (selfLoop) {
            return { status: "SELF_LOOP", message: `Bucle final alcanzado en PC = ${hex32(this.pc)}.` };
        }
        if (this.breakpoints.has(this.pc)) {
            return { status: "BREAKPOINT", message: `Breakpoint alcanzado en PC = ${hex32(this.pc)}.` };
        }
        return { status: "OK" };
    }

    illegal(instr) {
        this.halted = true;
        const msg = `Error: Instrucción inválida ${hex32(instr)} en PC = ${hex32(this.pc)}
`;
        this.log(msg);
        return { status: "ERROR", message: msg };
    }

    handleEcall() {
        const syscall = this.regs[17] >>> 0; // a7
        const a0 = this.regs[10] >>> 0;
        const a1 = this.regs[11] >>> 0;
        const stdinEl = document.getElementById("stdinInput");

        switch (syscall) {
            case 1: // print_int
                this.log(String(a0 | 0));
                break;
            case 4: { // print_string
                let s = "";
                let addr = a0;
                while (true) {
                    const ch = this.mem.read8(addr++);
                    if (ch === 0) break;
                    s += String.fromCharCode(ch);
                }
                this.log(s);
                break;
            }
            case 5: { // read_int
                let val = 0;
                if (stdinEl && stdinEl.value.trim() !== "") {
                    val = parseInt(stdinEl.value.trim(), 10) || 0;
                    stdinEl.value = "";
                } else {
                    const inp = prompt("ecall read_int (5) - Ingrese un entero:", "0");
                    val = parseInt(inp || "0", 10) || 0;
                }
                this.setReg(10, val >>> 0);
                break;
            }
            case 8: { // read_string
                let str = "";
                if (stdinEl && stdinEl.value !== "") {
                    str = stdinEl.value;
                    stdinEl.value = "";
                } else {
                    str = prompt("ecall read_string (8) - Ingrese texto:", "") || "";
                }
                const maxLen = Math.max(0, (a1 >>> 0) - 1);
                const n = Math.min(str.length, maxLen);
                for (let i = 0; i < n; i++) {
                    this.mem.write8(a0 + i, str.charCodeAt(i) & 0xFF);
                }
                this.mem.write8(a0 + n, 0);
                break;
            }
            case 9: { // sbrk
                const ptr = this.heapBreak;
                this.heapBreak = ((this.heapBreak + a0 + 3) & ~3) >>> 0;
                this.setReg(10, ptr);
                break;
            }
            case 10: // exit
                this.halted = true;
                this.log(`
[ecall 10] Programa terminado exitosamente.
`);
                return { status: "HALTED", message: "Programa terminado mediante ecall 10." };
            case 11: // print_char
                this.log(String.fromCharCode(a0 & 0xFF));
                break;
            case 34: // print_hex
                this.log(hex32(a0));
                break;
            case 93: // exit2
                this.halted = true;
                this.log(`
[ecall 93] Programa terminado con código ${a0 | 0}.
`);
                return { status: "HALTED", message: `Exit (${a0 | 0})` };
        }
        return { status: "OK" };
    }
}

// UI Controller
const consoleOut = document.getElementById("consoleOutput");
function appendLog(txt) {
    consoleOut.textContent += txt;
    consoleOut.scrollTop = consoleOut.scrollHeight;
}

const sim = new RiscVSimulator(appendLog);
let currentMemBase = 0x00001000;
let runTimer = null;

function formatRegValue(val, fmt) {
    val = val >>> 0;
    if (fmt === "signed") return String(val | 0);
    if (fmt === "unsigned") return String(val);
    return (val >>> 0).toString(16).toUpperCase().padStart(8, "0");
}

function renderRegisters() {
    const tbody = document.getElementById("regTableBody");
    const fmt = document.getElementById("regFormatSelect").value;
    let html = `<tr class="pc-row ${sim.pc !== sim.prevPc ? 'changed' : ''}">
        <td>pc</td>
        <td class="reg-abi">PC</td>
        <td>${formatRegValue(sim.pc, fmt)}</td>
    </tr>`;

    for (let i = 0; i < 32; i++) {
        const changed = sim.regs[i] !== sim.prevRegs[i];
        html += `<tr class="${changed ? 'changed' : ''}">
            <td>x${i}</td>
            <td class="reg-abi">${ABI_NAMES[i]}</td>
            <td>${formatRegValue(sim.regs[i], fmt)}</td>
        </tr>`;
    }
    tbody.innerHTML = html;
    document.getElementById("cycleCounter").textContent = `Steps: ${sim.steps}`;
}

function renderDisassembly(scrollToPc = false) {
    const tbody = document.getElementById("disasmTableBody");
    const start = sim.codeStart;
    const end = Math.max(sim.codeEnd, ((sim.pc + 32) >>> 0));
    let html = "";

    for (let addr = start; addr < end; addr += 4) {
        if (sim.symbols.has(addr)) {
            html += `<tr class="symbol-row"><td colspan="4">${hexWordRaw(addr)} &lt;${sim.symbols.get(addr)}&gt;:</td></tr>`;
        }
        const word = sim.mem.read32(addr);
        const asm = disassembleInstruction(word, addr, sim.symbols);
        const isPc = (addr === sim.pc);
        const hasBp = sim.breakpoints.has(addr);
        html += `<tr class="${isPc ? 'active-pc' : ''}" data-addr="${addr}">
            <td><input type="checkbox" class="bp-check" data-addr="${addr}" ${hasBp ? 'checked' : ''} /></td>
            <td>${hexWordRaw(addr)}</td>
            <td>${hexWordRaw(word)}</td>
            <td>${asm}</td>
        </tr>`;
    }
    tbody.innerHTML = html;

    tbody.querySelectorAll(".bp-check").forEach(cb => {
        cb.addEventListener("change", (e) => {
            const a = Number(e.target.dataset.addr) >>> 0;
            if (e.target.checked) sim.breakpoints.add(a);
            else sim.breakpoints.delete(a);
        });
    });

    if (scrollToPc) {
        const activeRow = tbody.querySelector("tr.active-pc");
        if (activeRow) activeRow.scrollIntoView({ block: "nearest" });
    }
}

function renderMemory() {
    const thead = document.getElementById("memTableHead");
    const tbody = document.getElementById("memTableBody");
    const wordsPerRow = parseInt(document.getElementById("memWordsPerRow").value, 10) || 4;
    const bytesPerRow = wordsPerRow * 4;
    const fmt = document.getElementById("regFormatSelect").value;

    let headHtml = `<tr><th>Address</th>`;
    for (let w = 0; w < wordsPerRow; w++) {
        headHtml += `<th>+${(w * 4).toString(16).toUpperCase()}</th>`;
    }
    headHtml += `<th>ASCII</th></tr>`;
    thead.innerHTML = headHtml;

    let bodyHtml = "";
    const numRows = 24;
    const alignedBase = (currentMemBase & ~(bytesPerRow - 1)) >>> 0;

    for (let r = 0; r < numRows; r++) {
        const rowAddr = (alignedBase + r * bytesPerRow) >>> 0;
        bodyHtml += `<tr><td class="mem-addr">${hexWordRaw(rowAddr)}</td>`;
        let ascii = "";
        for (let w = 0; w < wordsPerRow; w++) {
            const wAddr = (rowAddr + w * 4) >>> 0;
            const word = sim.mem.read32(wAddr);
            const cellStr = formatRegValue(word, fmt);
            bodyHtml += `<td class="mem-word ${word !== 0 ? 'nonzero' : ''}" title="${hex32(wAddr)} = ${word | 0}">${cellStr}</td>`;
            for (let b = 0; b < 4; b++) {
                const byteVal = sim.mem.read8(wAddr + b);
                ascii += (byteVal >= 32 && byteVal <= 126) ? String.fromCharCode(byteVal) : ".";
            }
            ascii += " ";
        }
        bodyHtml += `<td class="mem-ascii">${ascii.replace(/</g, "&lt;")}</td></tr>`;
    }
    tbody.innerHTML = bodyHtml;
}

function setStatusBadge(state, text) {
    const badge = document.getElementById("statusBadge");
    badge.className = `status-badge ${state}`;
    badge.textContent = text;
}

function refreshAll(scrollToPc = true) {
    renderRegisters();
    renderDisassembly(scrollToPc);
    renderMemory();
}

function loadPreset(name) {
    stopRunning();
    const preset = PRESET_PROGRAMS[name];
    if (!preset) return;
    const binStr = atob(preset.b64);
    const bytes = new Uint8Array(binStr.length);
    for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
    sim.loadBytes(bytes, preset.filename);
    if (name === "riscvtest") {
        currentMemBase = 0x00000040;
        document.getElementById("memAddressInput").value = "0x00000060";
    } else {
        currentMemBase = 0x00001000;
        document.getElementById("memAddressInput").value = "0x00001000";
    }
    setStatusBadge("stopped", "Stopped");
    refreshAll(true);
}

function stopRunning() {
    if (runTimer) {
        clearInterval(runTimer);
        runTimer = null;
    }
    document.getElementById("btnStop").disabled = true;
    document.getElementById("btnRun").disabled = false;
    document.getElementById("btnStep").disabled = false;
}

document.getElementById("btnStep").addEventListener("click", () => {
    const res = sim.step();
    if (res.status === "HALTED" || res.status === "SELF_LOOP") {
        setStatusBadge("halted", "Done");
    } else if (res.status === "ERROR") {
        setStatusBadge("error", "Error");
    } else {
        setStatusBadge("stopped", "Stopped");
    }
    refreshAll(true);
});

document.getElementById("btnRun").addEventListener("click", () => {
    if (sim.halted) return;
    setStatusBadge("running", "Running");
    document.getElementById("btnStop").disabled = false;
    document.getElementById("btnRun").disabled = true;

    runTimer = setInterval(() => {
        for (let i = 0; i < 64; i++) {
            const res = sim.step();
            if (res.status !== "OK") {
                stopRunning();
                if (res.message) appendLog(`[Simulador] ${res.message}
`);
                if (res.status === "ERROR") setStatusBadge("error", "Error");
                else if (res.status === "BREAKPOINT" || res.status === "EBREAK") setStatusBadge("stopped", "Breakpoint");
                else setStatusBadge("halted", "Completed");
                refreshAll(true);
                return;
            }
        }
        refreshAll(true);
    }, 16);
});

document.getElementById("btnStop").addEventListener("click", () => {
    stopRunning();
    setStatusBadge("stopped", "Stopped");
    refreshAll(true);
});

document.getElementById("btnReset").addEventListener("click", () => {
    stopRunning();
    if (sim.lastBuffer) {
        sim.loadBytes(sim.lastBuffer, sim.lastFilename);
        setStatusBadge("stopped", "Stopped");
        refreshAll(true);
    }
});

document.getElementById("presetSelect").addEventListener("change", (e) => {
    loadPreset(e.target.value);
});

const fileInput = document.getElementById("fileInput");
document.getElementById("btnLoadFile").addEventListener("click", () => fileInput.click());
document.getElementById("btnDrawerLoad").addEventListener("click", () => fileInput.click());

fileInput.addEventListener("change", (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
        const bytes = new Uint8Array(ev.target.result);
        stopRunning();
        sim.loadBytes(bytes, file.name);
        setStatusBadge("stopped", "Stopped");
        refreshAll(true);
    };
    reader.readAsArrayBuffer(file);
});

document.getElementById("regFormatSelect").addEventListener("change", () => refreshAll(false));
document.getElementById("memWordsPerRow").addEventListener("change", () => renderMemory());

document.getElementById("btnGoMem").addEventListener("click", () => {
    const raw = document.getElementById("memAddressInput").value.trim();
    const regIdx = ABI_NAMES.indexOf(raw);
    if (regIdx >= 0) {
        currentMemBase = sim.regs[regIdx];
    } else if (raw.toLowerCase() === "pc") {
        currentMemBase = sim.pc;
    } else {
        const parsed = Number(raw.startsWith("0x") ? raw : "0x" + raw);
        if (!Number.isNaN(parsed)) currentMemBase = parsed >>> 0;
    }
    renderMemory();
});

document.querySelectorAll("[data-jump]").forEach(btn => {
    btn.addEventListener("click", () => {
        const target = btn.dataset.jump;
        document.getElementById("memAddressInput").value = target;
        currentMemBase = Number(target) >>> 0;
        renderMemory();
    });
});

document.getElementById("btnFollowPc").addEventListener("click", () => renderDisassembly(true));
document.getElementById("btnClearBp").addEventListener("click", () => {
    sim.breakpoints.clear();
    renderDisassembly(false);
});
document.getElementById("btnClearLog").addEventListener("click", () => {
    consoleOut.textContent = "";
});
document.getElementById("btnToggleLoadSave").addEventListener("click", () => {
    document.getElementById("loadSaveDrawer").classList.toggle("hidden");
});

// Save Raw Binary (.bin) - Appendix B feature
document.getElementById("btnSaveRaw").addEventListener("click", () => {
    const sHex = document.getElementById("saveStartAddr").value.trim();
    const eHex = document.getElementById("saveEndAddr").value.trim();
    const start = parseInt(sHex, 16) || 0;
    const end   = parseInt(eHex, 16) || 0x100;
    if (end <= start) return;
    const out = new Uint8Array(end - start);
    for (let i = 0; i < out.length; i++) {
        out[i] = sim.mem.read8(start + i);
    }
    const blob = new Blob([out], { type: "application/octet-stream" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `memory_${sHex}_${eHex}.bin`;
    a.click();
    URL.revokeObjectURL(url);
});

// View Tabs
document.querySelectorAll(".tab-btn").forEach(btn => {
    btn.addEventListener("click", () => {
        document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        const mode = btn.dataset.tab;
        const disPane = document.getElementById("disasmPane");
        const memPane = document.getElementById("memoryPane");
        if (mode === "disasm") {
            disPane.style.display = "flex";
            memPane.style.display = "none";
        } else if (mode === "memory") {
            disPane.style.display = "none";
            memPane.style.display = "flex";
        } else {
            disPane.style.display = "flex";
            memPane.style.display = "flex";
        }
    });
});

// Keyboard shortcuts (F2 = Step, F3 = Run, F4 = Reset)
window.addEventListener("keydown", (e) => {
    if (e.key === "F2") { e.preventDefault(); document.getElementById("btnStep").click(); }
    if (e.key === "F3") { e.preventDefault(); document.getElementById("btnRun").click(); }
    if (e.key === "F4") { e.preventDefault(); document.getElementById("btnReset").click(); }
});

// Initialize preset (supports optional URL parameters ?preset=...&steps=...&autorun=1)
const urlParams = new URLSearchParams(window.location.search);
const initialPreset = urlParams.get("preset") || "quicksort";
document.getElementById("presetSelect").value = initialPreset;
loadPreset(initialPreset);

const autoSteps = parseInt(urlParams.get("steps") || "0", 10);
if (autoSteps > 0) {
    for (let i = 0; i < autoSteps && !sim.halted; i++) {
        sim.step();
    }
    refreshAll(true);
} else if (urlParams.get("autorun") === "1") {
    for (let i = 0; i < 100000 && !sim.halted; i++) {
        const res = sim.step();
        if (res.status !== "OK") {
            if (res.message) appendLog(`[Simulador] ${res.message}\n`);
            setStatusBadge(res.status === "ERROR" ? "error" : "halted", "Completed");
            break;
        }
    }
    refreshAll(true);
}
